import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  computed,
  ElementRef,
  HostBinding,
  HostListener,
  inject,
  input,
  NgZone,
  numberAttribute,
  OnDestroy,
  signal,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { QScrollShadowDirective } from '@questrade/allspark-angular-components/core/directives';
import { QSharedResizeObserverService } from '@questrade/allspark-angular-components/core/services';
import { injectDestroy, randomString } from '@questrade/allspark-angular-components/core/utils';
import { takeUntil } from 'rxjs/operators';
import { QScrollAreaDisplayMode } from './types/scroll-area-display-mode.type';
import { QScrollAreaVisibilityMode } from './types/scroll-area-visibility-mode.type';

type ScrollState = 'hidden' | 'scrolling' | 'interacting' | 'idle';

@Component({
  selector: 'q-scroll-area, [q-scroll-area], [qScrollArea]',
  imports: [QScrollShadowDirective],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  templateUrl: './scroll-area.component.html',
  styleUrl: './scroll-area.component.scss',
})
export class QScrollAreaComponent implements AfterViewInit, OnDestroy {
  @ViewChild('scrollAreaViewport', { static: true }) viewportRef!: ElementRef<HTMLElement>;
  @ViewChild('scrollbarX', { static: true }) scrollbarXRef!: ElementRef<HTMLElement>;
  @ViewChild('scrollbarY', { static: true }) scrollbarYRef!: ElementRef<HTMLElement>;
  @ViewChild('thumbX', { static: true }) thumbXRef!: ElementRef<HTMLElement>;
  @ViewChild('thumbY', { static: true }) thumbYRef!: ElementRef<HTMLElement>;
  @ViewChild('corner', { static: true }) cornerRef!: ElementRef<HTMLElement>;

  @HostBinding('class') _hostClass = 'q-scroll-area';
  @HostBinding('attr.data-qt') get _dataQtBinding(): string {
    return this.dataQt();
  }

  @HostListener('mouseenter') _onMouseEnter = (): void => this._handleMouseenter();
  @HostListener('mouseleave') _onMouseleave = (): void => this._handleMouseleave();
  @HostListener('window:pointermove', ['$event']) handlePointermove = (event: PointerEvent): void =>
    this._handlePointermove(event);
  @HostListener('window:pointerup', ['$event']) handlePointerUp = (event: PointerEvent): void =>
    this._handlePointerup(event);

  visibilityMode = input<QScrollAreaVisibilityMode>('hover');
  displayMode = input<QScrollAreaDisplayMode>('overlay');
  hideDelay = input(600, { transform: numberAttribute });
  enableScrollShadow = input(false, { transform: booleanAttribute });
  dataQt = input('q-scroll-area');

  _showScrollbarX = computed(() => this._getShowScrollbarX());
  _showScrollbarY = computed(() => this._getShowScrollbarY());
  _shouldReserveSpaceX = computed(() => this._getShouldReserveSpaceX());
  _shouldReserveSpaceY = computed(() => this._getShouldReserveSpaceY());
  _showCorner = computed(() => this._showScrollbarX() && this._showScrollbarY());
  _viewportPaddingRight = computed(() => this._getViewportPaddingRight());
  _viewportPaddingBottom = computed(() => this._getViewportPaddingBottom());
  _thumbPositionX = 0;
  _thumbPositionY = 0;
  _ariaValueNowX = 0;
  _ariaValueNowY = 0;
  _thumbSizeX = 0;
  _thumbSizeY = 0;
  _scrollbarXSize = 0;
  _scrollbarYSize = 0;
  _cornerWidth = 0;
  _cornerHeight = 0;
  _viewportId = `q-scroll-area-viewport-id-${randomString()}`;

  private _hasOverflowX = signal(false);
  private _hasOverflowY = signal(false);
  private _scrollState = signal<ScrollState>('hidden');
  private _hideTimeout: ReturnType<typeof setTimeout> | null = null;
  private _dragAxis: 'x' | 'y' | null = null;
  private _dragStartPos = { x: 0, y: 0 };
  private _initialScrollPos = { left: 0, top: 0 };
  private _pointerOffset = { x: 0, y: 0 };
  private _originalScrollBehavior = '';
  private _resizeRAF = 0;
  private _isDragging = false;
  private _isDestroyed = false;
  private _scrollListenerCleanup: (() => void) | null = null;
  private _debouncedScrollEndCleanup: (() => void) | null = null;
  private _debouncedResizeCleanup: (() => void) | null = null;
  private _debouncedScrollEnd: (...args: unknown[]) => void = () => {};
  private _debouncedResize: (...args: unknown[]) => void = () => {};
  private readonly _resizeObserverService = inject(QSharedResizeObserverService);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _zone = inject(NgZone);
  private readonly _destroy$ = injectDestroy();

  ngAfterViewInit(): void {
    this._initializeResizeObserver();
    this._initializeScrollListener();
    this._initializeScrollbarSizes();
    this._initializeDebouncedCallbacks();
  }

  ngOnDestroy(): void {
    this._isDestroyed = true;

    if (this._hideTimeout) {
      clearTimeout(this._hideTimeout);
    }

    if (this._scrollListenerCleanup) {
      this._scrollListenerCleanup();
    }

    if (this._resizeRAF) {
      cancelAnimationFrame(this._resizeRAF);
    }

    if (this._debouncedScrollEndCleanup) {
      this._debouncedScrollEndCleanup();
    }

    if (this._debouncedResizeCleanup) {
      this._debouncedResizeCleanup();
    }
  }

  handleWheel(event: WheelEvent): void {
    const viewport = this.viewportRef.nativeElement;
    if (!viewport) return;

    viewport.offsetHeight;

    const hasOverflowX = viewport.scrollWidth > viewport.clientWidth;
    const hasOverflowY = viewport.scrollHeight > viewport.clientHeight;

    const isVerticalWheel = Math.abs(event.deltaY) > Math.abs(event.deltaX);
    const wheelDelta = isVerticalWheel ? event.deltaY : event.deltaX;
    const hasOverflow = isVerticalWheel ? hasOverflowY : hasOverflowX;

    if (hasOverflow && wheelDelta !== 0) {
      const currentScroll = isVerticalWheel ? viewport.scrollTop : viewport.scrollLeft;
      const maxScroll = isVerticalWheel
        ? viewport.scrollHeight - viewport.clientHeight
        : viewport.scrollWidth - viewport.clientWidth;

      const targetScrollPos = currentScroll + wheelDelta;

      if (this._isScrollingWithinScrollbarBounds(targetScrollPos, maxScroll)) {
        event.stopPropagation();
      }

      if (this.visibilityMode() === 'scroll') {
        this._handleInteraction();
      }
    }
  }

  handlePointerDown(event: PointerEvent, axis: 'x' | 'y'): void {
    event.preventDefault();

    const thumb = axis === 'x' ? this.thumbXRef.nativeElement : this.thumbYRef.nativeElement;

    if (event.target === thumb) {
      event.stopPropagation();
      this._handleThumbDrag(event, axis, thumb);
    } else {
      this._handleTrackClick(event, axis);
    }
  }

  private _handleTrackClick(event: PointerEvent, axis: 'x' | 'y'): void {
    const viewport = this.viewportRef.nativeElement;
    const track =
      axis === 'x' ? this.scrollbarXRef.nativeElement : this.scrollbarYRef.nativeElement;
    const trackRect = track.getBoundingClientRect();

    const clickPosition =
      axis === 'x' ? event.clientX - trackRect.left : event.clientY - trackRect.top;

    const thumbSize = axis === 'x' ? this._thumbSizeX : this._thumbSizeY;
    const thumbCenter = thumbSize / 2;

    const scrollPos = this._getScrollPositionFromPointer(clickPosition, thumbCenter, axis);

    if (axis === 'x') {
      viewport.scrollLeft = scrollPos;
    } else {
      viewport.scrollTop = scrollPos;
    }
  }

  private _handleThumbDrag(event: PointerEvent, axis: 'x' | 'y', thumb: HTMLElement): void {
    this._isDragging = true;
    this._dragAxis = axis;

    const viewport = this.viewportRef.nativeElement;
    this._originalScrollBehavior = viewport.style.scrollBehavior;
    viewport.style.scrollBehavior = 'auto';

    const thumbRect = thumb.getBoundingClientRect();
    this._pointerOffset = {
      x: event.clientX - thumbRect.left,
      y: event.clientY - thumbRect.top,
    };

    thumb.setPointerCapture(event.pointerId);
    this._dragStartPos = { x: event.clientX, y: event.clientY };
    this._initialScrollPos = {
      left: viewport.scrollLeft,
      top: viewport.scrollTop,
    };
  }

  private _handleInteraction(): void {
    if (this.visibilityMode() !== 'scroll') {
      return;
    }

    if (this._hideTimeout) {
      clearTimeout(this._hideTimeout);
    }
    this._scrollState.set('interacting');
    this._startHideTimeout();
  }

  private _initializeScrollListener(): void {
    this._zone.runOutsideAngular(() => {
      const viewport = this.viewportRef.nativeElement;
      let prevPosition = { left: viewport.scrollLeft, top: viewport.scrollTop };
      let rAF = 0;
      let removeUnlinkedListener: (() => void) | null = null;

      const addUnlinkedScrollListener = (handler: () => void): (() => void) => {
        const loop = (): void => {
          if (this._isDestroyed) return;
          const position = { left: viewport.scrollLeft, top: viewport.scrollTop };
          const isHorizontalScroll = prevPosition.left !== position.left;
          const isVerticalScroll = prevPosition.top !== position.top;
          if (isHorizontalScroll || isVerticalScroll) {
            handler();
          }
          prevPosition = position;
          rAF = requestAnimationFrame(loop);
        };
        rAF = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(rAF);
      };

      const debounceScrollEnd = this._createDebounceCallback(() => {
        if (removeUnlinkedListener) {
          removeUnlinkedListener();
          removeUnlinkedListener = null;
        }

        if (this.visibilityMode() === 'scroll') {
          this._debouncedScrollEnd();
        }
      }, 100).fn;

      const handleScroll = (): void => {
        debounceScrollEnd();

        if (this.visibilityMode() === 'scroll') {
          const currentState = this._scrollState();
          if (currentState !== 'interacting') {
            this._scrollState.set('scrolling');
          }
        }

        if (!removeUnlinkedListener) {
          removeUnlinkedListener = addUnlinkedScrollListener(() => {
            this._updateThumbPositions();
            this._cdr.detectChanges();
          });
        }

        this._updateThumbPositions();
        this._cdr.detectChanges();
      };

      this._updateCornerSizes();
      this._updateThumbPositions();
      viewport.addEventListener('scroll', handleScroll);

      this._scrollListenerCleanup = (): void => {
        viewport.removeEventListener('scroll', handleScroll);
        if (removeUnlinkedListener) {
          removeUnlinkedListener();
        }
      };
    });
  }

  private _initializeResizeObserver(): void {
    this._zone.runOutsideAngular(() => {
      const viewport = this.viewportRef.nativeElement;
      const content = viewport.firstElementChild;

      const handleResize = (): void => {
        if (this._isDestroyed) return;
        if (this._resizeRAF) cancelAnimationFrame(this._resizeRAF);
        this._resizeRAF = requestAnimationFrame(() => {
          if (this._isDestroyed) return;
          this._debouncedResize();
        });
      };

      this._resizeObserverService
        .observe(viewport)
        ?.pipe(takeUntil(this._destroy$))
        .subscribe(() => handleResize());

      if (content) {
        this._resizeObserverService
          .observe(content)
          ?.pipe(takeUntil(this._destroy$))
          .subscribe(() => handleResize());
      }

      requestAnimationFrame(() => {
        if (this._isDestroyed) return;
        this._updateScrollbar(true);
        this._updateCornerSizes();
        this._updateThumbPositions();
      });
    });
  }

  private _startHideTimeout(): void {
    if (this._hideTimeout) {
      clearTimeout(this._hideTimeout);
    }
    this._hideTimeout = setTimeout(() => {
      this._zone.run(() => {
        if (this.visibilityMode() === 'hover') {
          this._scrollState.set('hidden');
          return;
        }

        if (this._isDragging) {
          return;
        }
        this._scrollState.set('hidden');
      });
    }, this.hideDelay());
  }

  private _updateScrollbar(runChangeDetection = true): void {
    const viewport = this.viewportRef.nativeElement;

    const hasOverflowX = viewport.scrollWidth > viewport.clientWidth;
    const hasOverflowY = viewport.scrollHeight > viewport.clientHeight;

    this._hasOverflowX.set(hasOverflowX);
    this._hasOverflowY.set(hasOverflowY);

    if (runChangeDetection) {
      this._cdr.detectChanges();
    }
  }

  private _updateThumbPositions(): void {
    const viewport = this.viewportRef.nativeElement;

    if (this._showScrollbarX()) {
      const scrollbar = this.scrollbarXRef.nativeElement;
      const computedStyle = getComputedStyle(scrollbar);

      const sizes = {
        content: viewport.scrollWidth,
        viewport: viewport.clientWidth,
        scrollbar: {
          size: scrollbar.clientWidth - (this._showCorner() ? this._cornerWidth : 0),
          paddingStart: this._toInt(computedStyle.paddingLeft),
          paddingEnd: this._toInt(computedStyle.paddingRight),
        },
      };

      this._thumbSizeX = this._getThumbSize(sizes);
      this._thumbPositionX = this._getThumbOffsetFromScroll(viewport.scrollLeft, sizes);
      this._ariaValueNowX =
        (viewport.scrollLeft / (viewport.scrollWidth - viewport.clientWidth)) * 100;
    }

    if (this._showScrollbarY()) {
      const scrollbar = this.scrollbarYRef.nativeElement;
      const computedStyle = getComputedStyle(scrollbar);

      const sizes = {
        content: viewport.scrollHeight,
        viewport: viewport.clientHeight,
        scrollbar: {
          size: scrollbar.clientHeight - (this._showCorner() ? this._cornerHeight : 0),
          paddingStart: this._toInt(computedStyle.paddingTop),
          paddingEnd: this._toInt(computedStyle.paddingBottom),
        },
      };

      this._thumbSizeY = this._getThumbSize(sizes);
      this._thumbPositionY = this._getThumbOffsetFromScroll(viewport.scrollTop, sizes);
      this._ariaValueNowY =
        (viewport.scrollTop / (viewport.scrollHeight - viewport.clientHeight)) * 100;
    }
  }

  private _updateCornerSizes(): void {
    if (this._showCorner()) {
      this._cornerWidth = this.scrollbarYRef.nativeElement.offsetWidth;
      this._cornerHeight = this.scrollbarXRef.nativeElement.offsetHeight;
    } else {
      this._cornerWidth = 0;
      this._cornerHeight = 0;
    }
    this._cdr.detectChanges();
  }

  private _createDebounceCallback<T extends (...args: unknown[]) => void>(
    callback: T,
    delay: number,
  ): { fn: (...args: Parameters<T>) => void; cleanup: () => void } {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;

    const fn = (...args: Parameters<T>): void => {
      if (timeoutId) clearTimeout(timeoutId);
      timeoutId = setTimeout(() => {
        this._zone.run(() => callback(...args));
      }, delay);
    };

    const cleanup = (): void => {
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
    };

    return { fn, cleanup };
  }

  private _handleMouseenter(): void {
    if (this.visibilityMode() === 'hover') {
      if (this._hideTimeout) {
        clearTimeout(this._hideTimeout);
        this._hideTimeout = null;
      }
      this._scrollState.set('interacting');
      this._updateScrollbar(true);
      this._updateThumbPositions();
    } else if (this.visibilityMode() === 'scroll') {
      const currentState = this._scrollState();
      if (currentState === 'scrolling' || currentState === 'idle') {
        this._scrollState.set('interacting');
      }
    }
  }

  private _handleMouseleave(): void {
    if (this.visibilityMode() === 'hover') {
      this._startHideTimeout();
    } else if (this.visibilityMode() === 'scroll') {
      const currentState = this._scrollState();
      if (currentState === 'interacting') {
        this._scrollState.set('idle');
        this._startHideTimeout();
      }
    }
  }

  private _handlePointermove(event: PointerEvent): void {
    if (!this._isDragging || !this._dragAxis) return;

    this._zone.runOutsideAngular(() => {
      const viewport = this.viewportRef.nativeElement;
      const scrollbar =
        this._dragAxis === 'x'
          ? this.scrollbarXRef.nativeElement
          : this.scrollbarYRef.nativeElement;

      const scrollbarRect = scrollbar.getBoundingClientRect();
      const pointerPos =
        this._dragAxis === 'x'
          ? event.clientX - scrollbarRect.left
          : event.clientY - scrollbarRect.top;

      const pointerOffset = this._dragAxis === 'x' ? this._pointerOffset.x : this._pointerOffset.y;
      const scrollPos = this._getScrollPositionFromPointer(
        pointerPos,
        pointerOffset,
        this._dragAxis as 'x' | 'y',
      );

      if (this._dragAxis === 'x') {
        viewport.scrollLeft = scrollPos;
      } else {
        viewport.scrollTop = scrollPos;
      }
    });
  }

  private _handlePointerup(event: PointerEvent): void {
    if (!this._isDragging) return;

    const thumb =
      this._dragAxis === 'x' ? this.thumbXRef.nativeElement : this.thumbYRef.nativeElement;

    if (thumb.hasPointerCapture(event.pointerId)) {
      thumb.releasePointerCapture(event.pointerId);
    }

    const viewport = this.viewportRef.nativeElement;
    viewport.style.scrollBehavior = this._originalScrollBehavior || '';

    this._isDragging = false;
    this._dragAxis = null;
  }

  private _getShowScrollbarX(): boolean {
    const state = this._scrollState();
    const hasOverflowX = this._hasOverflowX();
    const visibilityMode = this.visibilityMode();

    if (!hasOverflowX) return false;

    switch (visibilityMode) {
      case 'always':
      case 'auto':
        return true;
      case 'scroll':
      case 'hover':
        return state === 'scrolling' || state === 'interacting' || state === 'idle';
      default:
        return false;
    }
  }

  private _getShowScrollbarY(): boolean {
    const state = this._scrollState();
    const hasOverflowY = this._hasOverflowY();
    const visibilityMode = this.visibilityMode();

    if (!hasOverflowY) return false;

    switch (visibilityMode) {
      case 'always':
      case 'auto':
        return true;
      case 'scroll':
      case 'hover':
        return state === 'scrolling' || state === 'interacting' || state === 'idle';
      default:
        return false;
    }
  }

  private _getShouldReserveSpaceX(): boolean {
    const hasOverflowX = this._hasOverflowX();
    const displayMode = this.displayMode();
    const visibilityMode = this.visibilityMode();

    if (displayMode === 'overlay') return false;
    switch (visibilityMode) {
      case 'always':
      case 'scroll':
      case 'hover':
        return true;
      case 'auto':
        return hasOverflowX;
      default:
        return false;
    }
  }

  private _getShouldReserveSpaceY(): boolean {
    const hasOverflowY = this._hasOverflowY();
    const displayMode = this.displayMode();
    const visibilityMode = this.visibilityMode();

    if (displayMode === 'overlay') return false;
    switch (visibilityMode) {
      case 'always':
      case 'scroll':
      case 'hover':
        return true;
      case 'auto':
        return hasOverflowY;
      default:
        return false;
    }
  }

  private _getViewportPaddingRight(): number | null {
    if (!this._shouldReserveSpaceY()) return null;
    if (this._showCorner()) {
      return Math.max(this._scrollbarYSize, this._cornerWidth);
    }
    return this._scrollbarYSize;
  }

  private _getViewportPaddingBottom(): number | null {
    if (!this._shouldReserveSpaceX()) return null;
    if (this._showCorner()) {
      return Math.max(this._scrollbarXSize, this._cornerHeight);
    }
    return this._scrollbarXSize;
  }

  private _initializeScrollbarSizes(): void {
    this._scrollbarXSize = this.scrollbarXRef.nativeElement.offsetHeight;
    this._scrollbarYSize = this.scrollbarYRef.nativeElement.offsetWidth;
  }

  private _initializeDebouncedCallbacks(): void {
    const scrollEndCallback = this._createDebounceCallback(() => {
      if (this.visibilityMode() === 'hover') {
        return;
      }
      this._scrollState.set('idle');
      this._startHideTimeout();
    }, 100);
    this._debouncedScrollEnd = scrollEndCallback.fn;
    this._debouncedScrollEndCleanup = scrollEndCallback.cleanup;

    const resizeCallback = this._createDebounceCallback(() => {
      this._updateScrollbar();
      this._updateCornerSizes();
      this._updateThumbPositions();
    }, 10);
    this._debouncedResize = resizeCallback.fn;
    this._debouncedResizeCleanup = resizeCallback.cleanup;
  }

  private _isScrollingWithinScrollbarBounds(scrollPos: number, maxScrollPos: number): boolean {
    return scrollPos > 0 && scrollPos < maxScrollPos;
  }

  private _linearScale(
    input: readonly [number, number],
    output: readonly [number, number],
  ): (value: number) => number {
    return (value: number) => {
      if (input[0] === input[1] || output[0] === output[1]) return output[0];
      const ratio = (output[1] - output[0]) / (input[1] - input[0]);
      return output[0] + ratio * (value - input[0]);
    };
  }

  private _clamp(value: number, [min, max]: readonly [number, number]): number {
    return Math.min(max, Math.max(min, value));
  }

  private _toInt(value?: string): number {
    return value ? parseInt(value, 10) : 0;
  }

  private _getThumbRatio(viewportSize: number, contentSize: number): number {
    const ratio = viewportSize / contentSize;
    return isNaN(ratio) ? 0 : ratio;
  }

  private _getThumbSize(sizes: {
    content: number;
    viewport: number;
    scrollbar: { size: number; paddingStart: number; paddingEnd: number };
  }): number {
    const ratio = this._getThumbRatio(sizes.viewport, sizes.content);
    const scrollbarPadding = sizes.scrollbar.paddingStart + sizes.scrollbar.paddingEnd;
    const thumbSize = (sizes.scrollbar.size - scrollbarPadding) * ratio;
    return Math.max(thumbSize, 18);
  }

  private _getThumbOffsetFromScroll(
    scrollPos: number,
    sizes: {
      content: number;
      viewport: number;
      scrollbar: { size: number; paddingStart: number; paddingEnd: number };
    },
  ): number {
    const thumbSizePx = this._getThumbSize(sizes);
    const scrollbarPadding = sizes.scrollbar.paddingStart + sizes.scrollbar.paddingEnd;
    const scrollbar = sizes.scrollbar.size - scrollbarPadding;
    const maxScrollPos = sizes.content - sizes.viewport;
    const maxThumbPos = scrollbar - thumbSizePx;
    const scrollClampRange = [0, maxScrollPos] as const;
    const scrollWithoutMomentum = this._clamp(scrollPos, scrollClampRange);
    const interpolate = this._linearScale([0, maxScrollPos], [0, maxThumbPos]);
    return interpolate(scrollWithoutMomentum);
  }

  private _getScrollPositionFromPointer(
    pointerPos: number,
    pointerOffset: number,
    axis: 'x' | 'y',
  ): number {
    const viewport = this.viewportRef.nativeElement;
    const scrollbar =
      axis === 'x' ? this.scrollbarXRef.nativeElement : this.scrollbarYRef.nativeElement;

    const isHorizontal = axis === 'x';
    const contentSize = isHorizontal ? viewport.scrollWidth : viewport.scrollHeight;
    const viewportSize = isHorizontal ? viewport.clientWidth : viewport.clientHeight;
    let scrollbarSize = isHorizontal ? scrollbar.clientWidth : scrollbar.clientHeight;

    if (this._showCorner()) {
      scrollbarSize -= isHorizontal ? this._cornerWidth : this._cornerHeight;
    }

    const computedStyle = getComputedStyle(scrollbar);
    const sizes = {
      content: contentSize,
      viewport: viewportSize,
      scrollbar: {
        size: scrollbarSize,
        paddingStart: isHorizontal
          ? this._toInt(computedStyle.paddingLeft)
          : this._toInt(computedStyle.paddingTop),
        paddingEnd: isHorizontal
          ? this._toInt(computedStyle.paddingRight)
          : this._toInt(computedStyle.paddingBottom),
      },
    };

    const thumbSizePx = this._getThumbSize(sizes);
    const thumbCenter = thumbSizePx / 2;
    const offset = pointerOffset || thumbCenter;
    const thumbOffsetFromEnd = thumbSizePx - offset;
    const minPointerPos = sizes.scrollbar.paddingStart + offset;
    const maxPointerPos = sizes.scrollbar.size - sizes.scrollbar.paddingEnd - thumbOffsetFromEnd;
    const maxScrollPos = sizes.content - sizes.viewport;
    const scrollRange = [0, maxScrollPos] as const;

    const interpolate = this._linearScale([minPointerPos, maxPointerPos], scrollRange);
    return interpolate(pointerPos);
  }
}
